head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > getSelectedIndex]<br/>컴포넌트에서 선택된 트리 아이템의 인덱스를 숫자로 반환합니다.",
    "validation" : [
        "트리 아이템의 인덱스는 Depth-First Search 방식으로 설정되며, moveNode() 메소드 실행 시 인덱스가 재설정 됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onclick"]);

    $c.gcm.createLabel('label="moveNode 를 수행하여 마지막 아이템을 index=2 위치로 이동 후 getLastChildIndex 수행하여 확인"', '', 'label1'); 

    $c.gcm.createBasicTreeView('', eList);
}



scwin.btn_getSelectedIndex_onclick = function (e) {
    let rtn ='';

    rtn = target1.getSelectedIndex();    
    wf_body_bottom.getObj("scwin").setReturnValue("return : "+ rtn);     

    let spanElement = document.querySelector('span[id*="target1_label_'+rtn+'"]');

    if (spanElement) {
        wf_body_bottom.getObj("scwin").setReturnValue("className: "+ spanElement.className);  
    }        
};



scwin.target1_onclick = function (e) {
    scwin.btn_getSelectedIndex_onclick();
}



scwin.btn_moveNode_onclick = function (e) {
	target1.moveNode(11, 1, true);
};
